(()=>{'use strict';const d=document;d.addEventListener('click',e=>{const b=e.target.closest('.zoho-edd-copy-btn');if(b){const el=d.getElementById(b.dataset.copyTarget||''),txt=el?.textContent?.trim()||'';if(!txt)return;const orig=b.textContent,ok=()=>{b.textContent='Copied!';setTimeout(()=>b.textContent=orig,1500)};if(navigator.clipboard?.writeText)navigator.clipboard.writeText(txt).then(ok).catch(()=>{});else{const t=d.createElement('textarea');t.value=txt;t.style.cssText='position:fixed;opacity:0';d.body.appendChild(t);t.select();try{d.execCommand('copy');ok()}catch(_){}t.remove()}return}const c=e.target.closest('#zp-edition-cards .zp-ed-card');if(c){const v=c.dataset.edition==='us'?'us':'in',inp=d.getElementById('zp-edition-input');if(inp)inp.value=v;d.querySelectorAll('#zp-edition-cards .zp-ed-card').forEach(el=>{const a=el.dataset.edition===v;el.classList.toggle('is-active',a);el.setAttribute('aria-checked',a?'true':'false')})}})})();